create or replace function private.is_platform_super_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from auth.users u join public.platform_admins pa on pa.user_id=u.id where u.id=(select auth.uid()) and lower(u.email)='islamiahiis243@gmail.com' and u.email_confirmed_at is not null and pa.admin_role='PLATFORM_SUPER_ADMIN'); $$;
revoke all on function private.is_platform_super_admin() from public,anon; grant execute on function private.is_platform_super_admin() to authenticated;
drop policy if exists company_registration_platform_read on public.company_registration_requests; create policy company_registration_platform_read on public.company_registration_requests for select to authenticated using(private.is_platform_super_admin());
drop policy if exists companies_platform_admin_read on public.companies; create policy companies_platform_admin_read on public.companies for select to authenticated using(private.is_platform_super_admin());
drop policy if exists company_admin_seats_platform_read on public.company_admin_seats; create policy company_admin_seats_platform_read on public.company_admin_seats for select to authenticated using(private.is_platform_super_admin());
drop policy if exists workspaces_platform_admin_read on public.workspaces; create policy workspaces_platform_admin_read on public.workspaces for select to authenticated using(private.is_platform_super_admin());
create or replace function public.resolve_my_active_context() returns jsonb language sql stable set search_path='' as $$ select case when (select auth.uid()) is null then jsonb_build_object('authenticated',false) else jsonb_build_object('authenticated',true,'user_id',(select auth.uid()),'is_platform_super_admin',private.is_platform_super_admin(),'workspaces',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'type',w.workspace_type,'name',w.display_name,'status',w.status,'company_id',w.company_id,'access_basis',case when w.workspace_type='PERSONAL' then 'OWNER' else 'ACTIVE_COMPANY_MEMBERSHIP' end) order by w.created_at) from public.workspaces w where (w.workspace_type='PERSONAL' and w.owner_user_id=(select auth.uid())) or (w.workspace_type='COMPANY' and exists(select 1 from public.company_memberships cm where cm.workspace_id=w.id and cm.user_id=(select auth.uid()) and cm.membership_status='ACTIVE'))),'[]'::jsonb),'projects',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'workspace_id',p.workspace_id,'project_code',p.project_code,'name',p.name,'status',p.status,'membership_id',pm.id,'permissions',coalesce((select jsonb_agg(pp.permission_code order by pp.permission_code) from public.project_membership_permissions pp join public.project_permission_catalog pc on pc.permission_code=pp.permission_code and pc.active=true where pp.project_membership_id=pm.id),'[]'::jsonb)) order by p.created_at) from public.project_memberships pm join public.projects p on p.id=pm.project_id and p.workspace_id=pm.workspace_id join public.company_memberships cm on cm.id=pm.company_membership_id and cm.workspace_id=pm.workspace_id and cm.user_id=(select auth.uid()) and cm.membership_status='ACTIVE' where pm.user_id=(select auth.uid()) and pm.membership_status='ACTIVE'),'[]'::jsonb)) end; $$;
revoke all on function public.resolve_my_active_context() from public,anon; grant execute on function public.resolve_my_active_context() to authenticated;
